"""Regenerate JSON and Markdown inline top-level shard wrappers.

Run from any directory with python3 stage1/cohere/json/testdata/generate_shards.py.
Counts come from the checked-in shard constants. Every wrapper enters parallel
execution before calling its shared runner; runners must not call Parallel again.
"""
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[4]


def count(source, constant):
    text = (ROOT / source).read_text()
    match = re.search(r"^const " + re.escape(constant) + r" = (\d+)$", text, re.M)
    if match is None:
        raise ValueError(f"missing static shard count {constant} in {source}")
    return int(match.group(1))


def wrappers(name, runner, total):
    return "\n".join(
        f"func {name}_{ordinal:04d}(t *testing.T) {{\n"
        f"\tt.Parallel()\n"
        f"\t{runner}(t, {ordinal})\n"
        f"}}\n"
        for ordinal in range(total)
    )


for name, runner, constant, filename in [
    ("TestPortMatchesGoCohere", "jsonPortTopShard", "testPortMatchesGoCohereShards", "top_portmatchesgocohere_test.go"),
    ("TestUpstreamRepositoryCorpusParity", "jsonUpstreamTopShard", "testUpstreamRepositoryCorpusParityShards", "top_upstreamrepositorycorpusparity_test.go"),
]:
    total = count("stage1/cohere/json/top_shared_test.go", constant)
    (ROOT / "stage1/cohere/json" / filename).write_text(
        "// Code generated by testdata/generate_shards.py. DO NOT EDIT.\n"
        "package json\n\nimport \"testing\"\n\n" + wrappers(name, runner, total)
    )

path = ROOT / "stage1/cohere/markdowninline/shard_units_test.go"
source = path.read_text()
marker = "// Code generated below by ../json/testdata/generate_shards.py. DO NOT EDIT.\n"
prefix = source.split("func TestMarkdownInline_0000(", 1)[0]
if marker in prefix:
    prefix = prefix.split(marker, 1)[0]
total = count("stage1/cohere/markdowninline/shards_test.go", "testMarkdownInlineShards")
path.write_text(prefix + marker + wrappers("TestMarkdownInline", "runInlineUnit", total))
